import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { BasicContainer } from 'components';
import { useCurrentPage, usePageFilterApplied, usePageFilterData } from 'hooks';

import { formatScopedGeoTitle } from '../../../../utils/formatScopedGeoTitle';
import { useInnovationHubPortfolioData } from '../../hooks/useInnovationHubPortfolioData';
import {
  getPortfolioBigNumbers,
  getPortfolioPieCharts,
} from './bffPortfolioData';
import { PortfolioBigNumbers } from './components/PortfolioBigNumbers/PortfolioBigNumbers';
import { PortfolioPieChart } from './components/PortfolioPieChart/PortfolioPieChart';
import {
  StyledInnovationPortfolioRoot,
  StyledPieChartsRow,
} from './InnovationPortfolio.styles';
import type { PortfolioCardData, PortfolioPieChartData } from './types';

export interface InnovationPortfolioProps {
  dataTestId?: string;
  mockPortfolioBigNumbers?: PortfolioCardData[];
  mockPortfolioPieCharts?: PortfolioPieChartData[];
}

export const InnovationPortfolio: React.FC<InnovationPortfolioProps> = ({
  dataTestId,
  mockPortfolioBigNumbers: mockBigNumbers,
  mockPortfolioPieCharts: mockPieCharts,
}) => {
  const { formatMessage } = useIntl();
  const { currentPage } = useCurrentPage();
  const { applied } = usePageFilterApplied(currentPage);
  const { dataFilters } = usePageFilterData(currentPage);
  const { data, loading, error } = useInnovationHubPortfolioData();

  const sectionTitle = useMemo(
    () =>
      formatScopedGeoTitle(formatMessage, {
        applied,
        dataFilters,
        globalTitleId: 'Innovation.InnovationHub.Overview.Portfolio.title',
        scopedTitleId:
          'Innovation.InnovationHub.Overview.Portfolio.sectionTitle',
      }),
    [applied, dataFilters, formatMessage],
  );

  const useMocks = Boolean(mockBigNumbers?.length && mockPieCharts?.length);

  const bigNumbers =
    useMocks && mockBigNumbers && mockPieCharts
      ? mockBigNumbers
      : getPortfolioBigNumbers(data);
  const pieCharts =
    useMocks && mockBigNumbers && mockPieCharts
      ? mockPieCharts
      : getPortfolioPieCharts(data);

  const portfolioLoading = useMocks ? false : loading;
  const portfolioError = useMocks ? null : error;

  return (
    <StyledInnovationPortfolioRoot data-testid={dataTestId}>
      <BasicContainer
        dataTestId="innovation-portfolio"
        layout={{
          background: '#fafafa',
          border: 'gray',
          bodyPadding: false,
        }}
        header={{
          title: sectionTitle,
          titleSize: 'H1',
        }}
      >
        <PortfolioBigNumbers
          data={bigNumbers}
          loading={portfolioLoading}
          error={portfolioError}
        />
        <StyledPieChartsRow>
          {pieCharts.map((chart) => (
            <PortfolioPieChart
              key={chart.id}
              chartId={chart.id}
              title={chart.title}
              slices={chart.slices}
              loading={portfolioLoading}
              dataTestId={`portfolio-pie-chart-${chart.id}`}
            />
          ))}
        </StyledPieChartsRow>
      </BasicContainer>
    </StyledInnovationPortfolioRoot>
  );
};
